/**
 * Funding-asset conversion. PRD sections 6 and 10.
 *
 * Obligations are always XUSD. A payer chooses which of the four assets funds
 * that obligation, and the recipient is always credited XUSD. This module owns
 * the one-way conversion from an XUSD obligation to the payer's source debit.
 *
 * The rate lives in the demo world (PRD section 11: reset restores the clock
 * and the mocked FX rate) and is passed in rather than read from a module-level
 * constant, so a reset cannot leave a stale rate behind in a warm serverless
 * instance.
 */

import { type Asset, type BaseUnits, mulDivRound, roundDiv } from './money';

/**
 * XSGD per 1 XUSD, scaled by {@link RATE_SCALE}.
 *
 * PRD section 6 states the mocked rate as "1XUSD = 1.31 XSGD", so the seeded
 * value is 1.31 * 1_000_000 = 1_310_000. Stored scaled and integral so that
 * conversion never touches a float.
 */
export type XsgdPerXusdRate = bigint;

/** The scale of `app.world.xsgd_per_xusd_e6`. */
export const RATE_SCALE = 1_000_000n;

/** The seeded rate. PRD section 6. */
export const DEFAULT_XSGD_PER_XUSD: XsgdPerXusdRate = 1_310_000n;

/**
 * What a payer is actually charged to discharge an XUSD obligation.
 *
 * PRD section 10 requires the conversion rate and the resulting source-asset
 * debit to be shown before confirmation, which is why this returns the rate it
 * used alongside the amount instead of just the number.
 */
export interface Conversion {
  /** The XUSD the recipient receives. Never altered by the funding choice. */
  readonly obligationXusd: BaseUnits;
  readonly fundingAsset: Asset;
  /** What leaves the payer's wallet, in `fundingAsset`. */
  readonly sourceDebit: BaseUnits;
  /**
   * XSGD per 1 XUSD, scaled by {@link RATE_SCALE}, or null for the 1:1 assets.
   * Present so the confirmation screen can state the rate it applied.
   */
  readonly rate: XsgdPerXusdRate | null;
  /** True when {@link sourceDebit} was rounded to the nearest base unit. */
  readonly rounded: boolean;
}

/**
 * Convert an XUSD obligation into the debit taken from the funding asset.
 *
 * USDC, USDT and XUSD fund XUSD at a mocked 1:1 (PRD section 6), so the debit
 * equals the obligation and no rounding occurs. XSGD applies the world rate.
 *
 * PRD section 10 words the XSGD case as "source debit = XUSD obligation / rate,
 * where rate is XUSD per 1 XSGD". Section 6 states the same rate the other way
 * up, as "1XUSD = 1.31 XSGD". Both describe one fact: discharging a 1 XUSD
 * obligation costs 1.31 XSGD. This module holds the rate in the section 6
 * orientation, XSGD per XUSD, and multiplies. The arithmetic is identical; the
 * multiplication is simply harder to invert by mistake.
 */
export function convert(
  obligationXusd: BaseUnits,
  fundingAsset: Asset,
  rate: XsgdPerXusdRate,
): Conversion {
  if (fundingAsset !== 'XSGD') {
    return {
      obligationXusd,
      fundingAsset,
      sourceDebit: obligationXusd,
      rate: null,
      rounded: false,
    };
  }
  if (rate <= 0n) {
    throw new RangeError('the XSGD rate must be positive');
  }
  const sourceDebit = mulDivRound(obligationXusd, rate, RATE_SCALE);
  const exact = obligationXusd * rate;
  return {
    obligationXusd,
    fundingAsset,
    sourceDebit,
    rate,
    rounded: exact % RATE_SCALE !== 0n,
  };
}

/** Render a scaled rate to four decimals, e.g. "1 XUSD = 1.3100 XSGD". */
export function formatRate(rate: XsgdPerXusdRate): string {
  const e4 = roundDiv(rate, 100n);
  return `1 XUSD = ${e4 / 10_000n}.${(e4 % 10_000n).toString().padStart(4, '0')} XSGD`;
}

src/core/lifecycle.ts.source:
/**
 * The payable obligation lifecycle. PRD section 7.
 *
 *   Draft -> Pending approval -> Approved -> Certified -> Issued -> Matured -> Settled
 *                                                                     |
 *                                                                     +-> Overdue
 *
 * PRD section 7 opens by insisting the obligation lifecycle is separate from
 * market activity and ownership history. That separation is structural here:
 * this module knows nothing about listings or bids, and market status is
 * derived from whether an active listing exists rather than stored as a second
 * field that must be kept in sync with this one.
 *
 * Transitions live in one table. Adding a state without saying who may move it
 * and from where is a compile error, which is the point.
 */

/** Who is acting. PRD section 5. */
export const ROLES = [
  'adata_preparer',
  'adata_checker',
  'supplier',
  'lender',
  'straitsx_admin',
] as const;
export type Role = (typeof ROLES)[number];

export const LIFECYCLE_STATUSES = [
  'draft',
  'pending_approval',
  'approved',
  'certified',
  'issued',
  'matured',
  'settled',
  'overdue',
] as const;
export type LifecycleStatus = (typeof LIFECYCLE_STATUSES)[number];

export const LIFECYCLE_EVENTS = [
  'submit',
  'approve',
  'certify',
  'issue',
  'mature',
  'settle',
  'mark_overdue',
] as const;
export type LifecycleEvent = (typeof LIFECYCLE_EVENTS)[number];

interface Transition {
  readonly from: LifecycleStatus;
  readonly to: LifecycleStatus;
  /**
   * Roles permitted to fire this event. The demo clock fires `mature` with no
   * human actor, so that row is empty and is driven by {@link dueStatusFor}.
   */
  readonly actors: readonly Role[];
  readonly label: string;
  /**
   * The same move in the imperative, for the sentence that says what a queue is
   * waiting for. `label` is the past tense the journal records after the fact;
   * this is the ask, before anyone has acted.
   */
  readonly action: string;
}

/**
 * The complete transition table.
 *
 * Maker-checker is enforced here as a role split (`adata_preparer` submits,
 * `adata_checker` approves) but the PRD also requires the two to be different
 * people, not merely different roles. That second half is an identity check the
 * caller performs, since this table sees roles rather than users.
 */
export const TRANSITIONS: Readonly<Record<LifecycleEvent, Transition>> = {
  submit: {
    from: 'draft',
    to: 'pending_approval',
    actors: ['adata_preparer'],
    label: 'Submitted for approval',
    action: 'submit it for approval',
  },
  approve: {
    from: 'pending_approval',
    to: 'approved',
    actors: ['adata_checker'],
    label: 'Approved by ADATA checker',
    action: 'approve it',
  },
  certify: {
    from: 'approved',
    to: 'certified',
    actors: ['straitsx_admin'],
    label: 'Certified and graded by StraitsX',
    action: 'certify it',
  },
  issue: {
    from: 'certified',
    to: 'issued',
    actors: ['adata_preparer', 'adata_checker', 'straitsx_admin'],
    label: 'Issued to supplier wallet',
    action: 'issue it to the supplier',
  },
  mature: {
    from: 'issued',
    to: 'matured',
    actors: [],
    label: 'Reached maturity',
    action: 'reach maturity',
  },
  settle: {
    from: 'matured',
    to: 'settled',
    actors: ['adata_preparer', 'adata_checker'],
    label: 'Settled to holders',
    action: 'settle it to the holders',
  },
  mark_overdue: {
    from: 'matured',
    to: 'overdue',
    actors: [],
    label: 'Passed due date unpaid',
    action: 'mark it overdue',
  },
};

/** States from which nothing further can happen. PRD section 7. */
const TERMINAL: ReadonlySet<LifecycleStatus> = new Set<LifecycleStatus>(['settled']);

export function isTerminal(status: LifecycleStatus): boolean {
  return TERMINAL.has(status);
}

/**
 * Whether tokens may move. PRD section 7: "each holder may hold, list, sell, or
 * transfer any quantity they own, up to their balance, before maturity."
 *
 * Maturity expires listings and bids, so only `issued` permits market activity.
 */
export function isTradeable(status: LifecycleStatus): boolean {
  return status === 'issued';
}

/** Whether the obligation is awaiting or has received its maturity payment. */
export function isDue(status: LifecycleStatus): boolean {
  return status === 'matured' || status === 'overdue';
}

/**
 * How a role is written inside a sentence. PRD section 5 names them in prose,
 * and swapping the underscores for spaces yields "adata preparer" and
 * "straitsx admin", which is neither the PRD's wording nor an organisation a
 * presenter can point at.
 *
 * Mid-sentence form only, which is what a refusal and the approval queue need.
 * The accounts table and the persona switcher keep their own title-case and
 * dotted spellings, because a table cell and a dropdown entry are not
 * sentences.
 */
export const ROLE_LABELS: Readonly<Record<Role, string>> = {
  adata_preparer: 'ADATA preparer',
  adata_checker: 'ADATA checker',
  supplier: 'supplier',
  lender: 'lender',
  straitsx_admin: 'StraitsX admin',
};

export type TransitionResult =
  | { readonly ok: true; readonly to: LifecycleStatus; readonly label: string }
  | { readonly ok: false; readonly reason: string };

/**
 * Check one transition.
 *
 * Returns a result rather than throwing because every caller is an API route
 * that must turn a refusal into inline feedback (PRD section 14), and an
 * exception would erase the reason on the way up.
 */
export function attempt(
  from: LifecycleStatus,
  event: LifecycleEvent,
  actor: Role,
): TransitionResult {
  const transition = TRANSITIONS[event];
  if (transition.from !== from) {
    return {
      ok: false,
      reason: `cannot ${event} a payable that is ${from.replace(/_/g, ' ')}; it must be ${transition.from.replace(/_/g, ' ')}`,
    };
  }
  if (transition.actors.length > 0 && !transition.actors.includes(actor)) {
    return { ok: false, reason: `${ROLE_LABELS[actor]} may not ${event} a payable` };
  }
  return { ok: true, to: transition.to, label: transition.label };
}

export interface PendingStep {
  readonly event: LifecycleEvent;
  readonly to: LifecycleStatus;
  /** Every role permitted to fire it. `issue` admits three. */
  readonly actors: readonly Role[];
  readonly action: string;
}

/**
 * Who the obligation is waiting on, and what it is waiting for them to do.
 *
 * PRD section 8 screen 3 is a queue, and a queue that says only what a payable
 * *is* leaves the presenter guessing which persona to become next. The answer
 * is already in {@link TRANSITIONS}: the pending step is the one transition out
 * of this state that a person fires. Deriving it here rather than branching per
 * status in the screen is what stops a new state being added without the queue
 * learning who owns it.
 *
 * Null where nobody is being waited on. `settled` is terminal, `issued` moves
 * on the clock rather than on anyone's say-so (see {@link dueStatusFor}), and
 * `overdue` has no transition out of it at all, because PRD section 4 puts
 * recovery workflows out of scope.
 */
export function pendingStep(status: LifecycleStatus): PendingStep | null {
  for (const event of LIFECYCLE_EVENTS) {
    const transition = TRANSITIONS[event];
    if (transition.from === status && transition.actors.length > 0) {
      return {
        event,
        to: transition.to,
        actors: transition.actors,
        action: transition.action,
      };
    }
  }
  return null;
}

/**
 * What the clock says the status should be, independent of who has acted.
 *
 * PRD section 7: "Matured: the payable is due, regardless of who holds it or
 * whether it was ever financed." Maturity is a function of time, so it is
 * derived here rather than waiting for someone to press a button. Advancing the
 * clock does not fund the obligation, so a matured payable stays matured until
 * ADATA settles it.
 */
export function dueStatusFor(current: LifecycleStatus, daysRemaining: number): LifecycleStatus {
  if (current !== 'issued') return current;
  return daysRemaining <= 0 ? 'matured' : 'issued';
}

/**
 * Whether a matured obligation has sat unpaid long enough to read as overdue.
 *
 * PRD section 7 defines overdue as "an unpaid obligation has passed its due
 * date" and section 11 provides a demo control to trigger the example case
 * directly, so the grace period is a presentation threshold rather than a
 * contractual term.
 */
export const OVERDUE_GRACE_DAYS = 0;

export function isOverdueByClock(status: LifecycleStatus, daysRemaining: number): boolean {
  return status === 'matured' && daysRemaining < -OVERDUE_GRACE_DAYS;
}

/**
 * Whether the supplier has taken delivery of the payable they were issued.
 *
 * PRD section 3 question 7 gives the supplier "an option to accept the
 * tokenised payable or reject it", but the section 7 lifecycle has no state for
 * it and the PRD never says what a rejection does to the obligation. Modelling
 * acceptance as receipt state on the first holding rather than as a lifecycle
 * state keeps the two questions separate and leaves the obligation diagram
 * exactly as the PRD draws it. See docs/ASSUMPTIONS.md for the rejection rule.
 */
export const RECEIPT_STATUSES = ['pending', 'accepted', 'rejected'] as const;
export type ReceiptStatus = (typeof RECEIPT_STATUSES)[number];

/**
 * A supplier may only trade what they have accepted. PRD section 8 screen 6
 * presents the inbox and holdings together, so an unaccepted payable is visible
 * but not yet actionable.
 */
export function canTradeReceipt(receipt: ReceiptStatus): boolean {
  return receipt === 'accepted';
}

/** Human labels for the status chips. */
export const STATUS_LABELS: Readonly<Record<LifecycleStatus, string>> = {
  draft: 'Draft',
  pending_approval: 'Pending approval',
  approved: 'Approved',
  certified: 'Certified',
  issued: 'Issued',
  matured: 'Matured',
  settled: 'Settled',
  overdue: 'Overdue',
};

src/core/market.ts.source:
/**
 * Marketplace filtering and sorting. PRD §8 screen 9.
 *
 *   "filter by maturity, tenor, sample grade, ticket size, and yield.
 *    Default sort is yield."
 *
 * Filtering happens here, in TypeScript, rather than in the SQL that fetches
 * listings. Three of the five criteria — tenor, yield, and the maturity cutoff
 * — are derived from the demo clock and the §6 pricing formulas, which live in
 * `src/core/pricing.ts`. Pushing them into SQL would mean a second
 * implementation of the yield formula that has to agree with the first
 * forever, and the two would drift the first time §6 was revisited. The
 * marketplace is a demo order book of tens of lots, so the cost of filtering
 * in memory is nothing and the cost of a duplicate formula is real.
 *
 * The filter is a plain object parsed from the URL query, so a filtered view is
 * a shareable link and the back button behaves. Nothing here touches React or
 * the database.
 */

import { type BaseUnits, BASE_UNITS_PER_UNIT } from './money';
import type { IsoDate } from './clock';

export const GRADES = ['AAA', 'AA', 'A'] as const;
export type Grade = (typeof GRADES)[number];

export const SORTS = ['yield', 'maturity', 'tenor', 'size', 'price'] as const;
export type Sort = (typeof SORTS)[number];

export const SORT_LABEL: Record<Sort, string> = {
  yield: 'Yield, highest first',
  maturity: 'Maturity, soonest first',
  tenor: 'Tenor, shortest first',
  size: 'Ticket size, largest first',
  price: 'Price, cheapest first',
};

export interface MarketFilter {
  /** Only lots maturing on or before this date. */
  maturityBy: IsoDate | null;
  /** Days remaining, inclusive on both ends. */
  tenorMin: number | null;
  tenorMax: number | null;
  /** Empty means every grade, which is not the same as none of them. */
  grades: readonly Grade[];
  /** Listed face, in base units. */
  sizeMin: BaseUnits | null;
  sizeMax: BaseUnits | null;
  /** Annualised lender yield, in percent. */
  yieldMin: number | null;
  sort: Sort;
}

export const NO_FILTER: MarketFilter = {
  maturityBy: null,
  tenorMin: null,
  tenorMax: null,
  grades: [],
  sizeMin: null,
  sizeMax: null,
  yieldMin: null,
  sort: 'yield',
};

/** The shape a listing has to have to be filtered. Narrower than `Listing`. */
export interface Filterable {
  grade: string | null;
  listedFaceBase: BaseUnits;
  maturityDate: IsoDate;
  quote: { daysRemaining: number; lenderYieldPercent: number | null; pricePercent: number };
}

export function applyFilter<T extends Filterable>(
  listings: readonly T[],
  filter: MarketFilter,
): T[] {
  const kept = listings.filter((l) => {
    if (filter.maturityBy !== null && l.maturityDate > filter.maturityBy) return false;
    if (filter.tenorMin !== null && l.quote.daysRemaining < filter.tenorMin) return false;
    if (filter.tenorMax !== null && l.quote.daysRemaining > filter.tenorMax) return false;
    if (filter.grades.length > 0 && !filter.grades.includes(l.grade as Grade)) return false;
    if (filter.sizeMin !== null && l.listedFaceBase < filter.sizeMin) return false;
    if (filter.sizeMax !== null && l.listedFaceBase > filter.sizeMax) return false;
    // A matured lot has no forward yield (§6 shows "Due" instead), so a yield
    // floor excludes it rather than treating a missing yield as zero.
    if (filter.yieldMin !== null) {
      if (l.quote.lenderYieldPercent === null) return false;
      if (l.quote.lenderYieldPercent < filter.yieldMin) return false;
    }
    return true;
  });
  return sortListings(kept, filter.sort);
}

function sortListings<T extends Filterable>(listings: T[], sort: Sort): T[] {
  const by: Record<Sort, (a: T, b: T) => number> = {
    yield: (a, b) => (b.quote.lenderYieldPercent ?? -1) - (a.quote.lenderYieldPercent ?? -1),
    maturity: (a, b) => a.maturityDate.localeCompare(b.maturityDate),
    tenor: (a, b) => a.quote.daysRemaining - b.quote.daysRemaining,
    size: (a, b) => (a.listedFaceBase < b.listedFaceBase ? 1 : a.listedFaceBase > b.listedFaceBase ? -1 : 0),
    price: (a, b) => a.quote.pricePercent - b.quote.pricePercent,
  };
  return [...listings].sort(by[sort]);
}

/** True when the filter would change what a lender sees. Drives the Clear control. */
export function isFiltered(filter: MarketFilter): boolean {
  return (
    filter.maturityBy !== null ||
    filter.tenorMin !== null ||
    filter.tenorMax !== null ||
    filter.grades.length > 0 ||
    filter.sizeMin !== null ||
    filter.sizeMax !== null ||
    filter.yieldMin !== null
  );
}

const ISO_DATE = /^\d{4}-\d{2}-\d{2}$/;

/**
 * Read a filter out of a URL query.
 *
 * Anything unparseable is dropped rather than rejected. A hand-edited or stale
 * link should show the marketplace, not an error page: this is a browse
 * control, and the worst outcome of ignoring a bad value is that the lender
 * sees more lots than they asked for and can see why from the controls.
 */
export function parseFilter(params: Record<string, string | string[] | undefined>): MarketFilter {
  const one = (key: string): string | null => {
    const v = params[key];
    const s = Array.isArray(v) ? v[0] : v;
    return s === undefined || s === '' ? null : s;
  };

  const int = (key: string): number | null => {
    const s = one(key);
    if (s === null) return null;
    const n = Number(s);
    return Number.isFinite(n) ? Math.trunc(n) : null;
  };

  const num = (key: string): number | null => {
    const s = one(key);
    if (s === null) return null;
    const n = Number(s);
    return Number.isFinite(n) ? n : null;
  };

  /** Display units in the URL, base units in the filter. `250000` reads as 250,000 XUSD. */
  const units = (key: string): BaseUnits | null => {
    const n = num(key);
    if (n === null || n < 0) return null;
    return (BigInt(Math.round(n * Number(BASE_UNITS_PER_UNIT))) as BaseUnits);
  };

  const maturityRaw = one('by');
  const gradesRaw = one('grade');
  const sortRaw = one('sort');

  return {
    maturityBy: maturityRaw !== null && ISO_DATE.test(maturityRaw) ? (maturityRaw as IsoDate) : null,
    tenorMin: int('tmin'),
    tenorMax: int('tmax'),
    grades:
      gradesRaw === null
        ? []
        : gradesRaw.split(',').filter((g): g is Grade => (GRADES as readonly string[]).includes(g)),
    sizeMin: units('smin'),
    sizeMax: units('smax'),
    yieldMin: num('ymin'),
    sort: (SORTS as readonly string[]).includes(sortRaw ?? '') ? (sortRaw as Sort) : 'yield',
  };
}

src/core/money.ts.source:
/**
 * Money and quantity primitives.
 *
 * PRD section 6: "XUSD 1.0000 of face value corresponds to 10,000 base units.
 * The minimum increment is one base unit (XUSD 0.0001); amounts between base
 * units are not representable. Store and compute quantities as integers of
 * those base units."
 *
 * Every amount in this system is a whole number of base units, carried as a
 * `bigint`. That choice is load-bearing rather than stylistic: JavaScript
 * refuses to mix `bigint` and `number` in arithmetic, so a float that leaks
 * into the money path fails to compile under TypeScript and throws at runtime
 * under plain JS. The representation enforces the invariant; no lint rule or
 * code-review convention is relied on.
 *
 * Percentages, yields and FX display values are derived `number`s. They are
 * outputs only. Nothing in this module accepts one back as money.
 */

/** Base units per 1.0000 unit of any supported asset. PRD section 6. */
export const BASE_UNITS_PER_UNIT = 10_000n;

/** Decimal places implied by {@link BASE_UNITS_PER_UNIT}. */
export const DECIMALS = 4;

declare const baseUnitsBrand: unique symbol;

/**
 * A whole number of base units. Always non-negative in stored balances and
 * holdings; intermediate differences may be negative, which is why the brand
 * does not itself assert positivity.
 */
export type BaseUnits = bigint & { readonly [baseUnitsBrand]: true };

/**
 * Hundredths of a percent. 97.85% is 9785. Used for price entry, never for
 * storing money. PRD section 9 lets a seller enter a price as a percentage of
 * face; that entry is converted to base units at the boundary and the base-unit
 * value is what is stored.
 */
export type PercentBps = number;

/** Basis points in 100%. */
export const BPS_PER_100_PERCENT = 10_000;

/** The four assets a wallet holds. PRD section 10. */
export const ASSETS = ['XUSD', 'USDC', 'USDT', 'XSGD'] as const;
export type Asset = (typeof ASSETS)[number];

/** Assets that may fund an XUSD obligation. PRD section 6. */
export type FundingAsset = Asset;

/**
 * Obligations, listings, bids and redemptions are denominated in XUSD only.
 * PRD section 4 puts issuing or listing in USDC, USDT or XSGD out of scope, so
 * the denomination is a constant rather than a field.
 */
export const DENOMINATION = 'XUSD' as const satisfies Asset;

export function isAsset(value: string): value is Asset {
  return (ASSETS as readonly string[]).includes(value);
}

// --- construction -----------------------------------------------------------

/** Unchecked cast. Internal to this module; callers use the parsers below. */
function brand(value: bigint): BaseUnits {
  return value as BaseUnits;
}

export const ZERO: BaseUnits = brand(0n);

/**
 * Build base units from a whole number of display units (250_000 -> 2.5e9 BU).
 * Rejects non-integers so a caller cannot smuggle 0.1 through as "whole".
 */
export function fromWholeUnits(units: number): BaseUnits {
  if (!Number.isSafeInteger(units)) {
    throw new RangeError(`fromWholeUnits expects a safe integer, received ${units}`);
  }
  return brand(BigInt(units) * BASE_UNITS_PER_UNIT);
}

/**
 * Parse a decimal string such as "250000.0000" or "1234.5" into base units.
 *
 * This is the boundary parser for anything a human typed or a seed file holds.
 * It rejects rather than rounds when the input carries more precision than the
 * base unit can represent, so "0.00005" is an error instead of a silent 0.
 */
export function parseUnits(input: string): BaseUnits {
  const text = input.trim();
  const match = /^(-?)(\d+)(?:\.(\d*))?$/.exec(text);
  if (!match) {
    throw new RangeError(`not a decimal amount: ${JSON.stringify(input)}`);
  }
  const [, sign, whole, fraction = ''] = match;
  if (fraction.length > DECIMALS) {
    const excess = fraction.slice(DECIMALS);
    if (/[^0]/.test(excess)) {
      throw new RangeError(
        `${input} needs more than ${DECIMALS} decimals; amounts between base units are not representable`,
      );
    }
  }
  const padded = fraction.padEnd(DECIMALS, '0').slice(0, DECIMALS);
  const magnitude = BigInt(whole) * BASE_UNITS_PER_UNIT + BigInt(padded || '0');
  return brand(sign === '-' ? -magnitude : magnitude);
}

/**
 * Adopt a value already known to be a whole number of base units, such as a
 * BIGINT column read back from Postgres.
 */
export function fromBaseUnits(value: bigint | string | number): BaseUnits {
  if (typeof value === 'number') {
    if (!Number.isSafeInteger(value)) {
      throw new RangeError(`base units must be a safe integer, received ${value}`);
    }
    return brand(BigInt(value));
  }
  return brand(BigInt(value));
}

// --- arithmetic -------------------------------------------------------------

export function add(a: BaseUnits, b: BaseUnits): BaseUnits {
  return brand(a + b);
}

export function sub(a: BaseUnits, b: BaseUnits): BaseUnits {
  return brand(a - b);
}

export function sum(values: readonly BaseUnits[]): BaseUnits {
  return brand(values.reduce<bigint>((acc, v) => acc + v, 0n));
}

export function isZero(a: BaseUnits): boolean {
  return a === 0n;
}

export function isNegative(a: BaseUnits): boolean {
  return a < 0n;
}

export function isPositive(a: BaseUnits): boolean {
  return a > 0n;
}

export function lt(a: BaseUnits, b: BaseUnits): boolean {
  return a < b;
}

export function lte(a: BaseUnits, b: BaseUnits): boolean {
  return a <= b;
}

export function gt(a: BaseUnits, b: BaseUnits): boolean {
  return a > b;
}

export function gte(a: BaseUnits, b: BaseUnits): boolean {
  return a >= b;
}

export function eq(a: BaseUnits, b: BaseUnits): boolean {
  return a === b;
}

export function min(a: BaseUnits, b: BaseUnits): BaseUnits {
  return a <= b ? a : b;
}

export function max(a: BaseUnits, b: BaseUnits): BaseUnits {
  return a >= b ? a : b;
}

/**
 * Divide `value * numerator / denominator`, rounding half away from zero.
 *
 * Every rounding decision in the system routes through here so the convention
 * is stated once rather than re-derived per call site. PRD section 6 requires
 * source-asset rounding to be explicit on confirmation; the caller reports the
 * rounded result, and this function guarantees the result is a whole base unit.
 */
export function mulDivRound(value: BaseUnits, numerator: bigint, denominator: bigint): BaseUnits {
  return brand(roundDiv(value * numerator, denominator));
}

/**
 * The same rounding on a plain bigint, for a scaled value that is not money.
 * A rate rendered to fewer decimals than it carries rounds by this rule too.
 */
export function roundDiv(product: bigint, denominator: bigint): bigint {
  if (denominator === 0n) {
    throw new RangeError('division by zero');
  }
  const negative = product < 0n !== denominator < 0n;
  const absProduct = product < 0n ? -product : product;
  const absDenominator = denominator < 0n ? -denominator : denominator;
  const quotient = (absProduct * 2n + absDenominator) / (absDenominator * 2n);
  return negative ? -quotient : quotient;
}

/**
 * Split `total` across `weights` so the parts sum back to `total` exactly.
 *
 * Maturity settlement pays each current holder in proportion to quantity held
 * (PRD section 7). Rounding each holder independently would leave a residue of
 * a few base units against the obligation, breaking the section 13 rule that
 * holdings sum to outstanding face. The largest-remainder method assigns the
 * residue deterministically, so the credits always reconcile to the debit.
 */
export function allocateProRata(total: BaseUnits, weights: readonly BaseUnits[]): BaseUnits[] {
  const weightTotal = weights.reduce<bigint>((acc, w) => acc + w, 0n);
  if (weightTotal <= 0n) {
    throw new RangeError('allocateProRata needs at least one positive weight');
  }
  const floors: bigint[] = [];
  const remainders: { index: number; remainder: bigint }[] = [];
  let assigned = 0n;
  weights.forEach((weight, index) => {
    const exact = total * weight;
    const floor = exact / weightTotal;
    floors.push(floor);
    assigned += floor;
    remainders.push({ index, remainder: exact - floor * weightTotal });
  });
  let residue = total - assigned;
  remainders.sort((a, b) => (b.remainder === a.remainder ? a.index - b.index : b.remainder > a.remainder ? 1 : -1));
  for (const { index } of remainders) {
    if (residue <= 0n) break;
    floors[index] += 1n;
    residue -= 1n;
  }
  return floors.map(brand);
}

// --- formatting -------------------------------------------------------------

/**
 * Render base units as a fixed-point decimal string.
 *
 * PRD section 6: two decimals in summary views, four in token detail. The
 * caller picks; the default is the full four so nothing is silently truncated.
 */
export function formatUnits(value: BaseUnits, decimals: number = DECIMALS): string {
  if (decimals < 0 || decimals > DECIMALS) {
    throw new RangeError(`decimals must be between 0 and ${DECIMALS}`);
  }
  const negative = value < 0n;
  const absolute = negative ? -value : value;
  const whole = absolute / BASE_UNITS_PER_UNIT;
  const fraction = absolute % BASE_UNITS_PER_UNIT;
  const fractionText = fraction.toString().padStart(DECIMALS, '0');
  const shown = roundFractionText(fractionText, decimals);
  const grouped = (shown.carry ? whole + 1n : whole).toLocaleString('en-US');
  const suffix = decimals === 0 ? '' : `.${shown.text}`;
  return `${negative ? '-' : ''}${grouped}${suffix}`;
}

/**
 * Truncate a four-digit fraction to `decimals`, rounding half up and reporting
 * a carry into the whole part. Returns one shape for every `decimals` value,
 * including the no-op case, so the caller never branches on which it got.
 */
function roundFractionText(fractionText: string, decimals: number): { text: string; carry: boolean } {
  if (decimals >= DECIMALS) return { text: fractionText, carry: false };
  const kept = fractionText.slice(0, decimals);
  const nextDigit = Number(fractionText[decimals] ?? '0');
  if (nextDigit < 5) return { text: kept, carry: false };
  const bumped = (BigInt(kept || '0') + 1n).toString();
  if (bumped.length > decimals) return { text: '0'.repeat(decimals), carry: true };
  return { text: bumped.padStart(decimals, '0'), carry: false };
}

/** Render with the asset ticker, e.g. "250,000.0000 XUSD". */
export function formatAmount(value: BaseUnits, asset: Asset, decimals: number = DECIMALS): string {
  return `${formatUnits(value, decimals)} ${asset}`;
}

/** Serialise for a JSON boundary. `bigint` has no JSON representation. */
export function toJson(value: BaseUnits): string {
  return value.toString();
}

